/** Recover net definitions for immutable prior-phase copper from native pad
 * identities. These are validation definitions, not new routing geometry. */
export function withFixedConnectionDefinitions(native:any){
 const connections=[...native.connections],known=new Set(connections.map((c:any)=>c.name))
 for(const t of native.traces??[]){const name=t.connection_name??t.source_trace_id;if(!name||known.has(name))continue;const ids=new Set([name,t.source_trace_id].filter(Boolean)),seen=new Set(),points=native.obstacles.flatMap((o:any)=>{const id=o.circuitJsonMetadata?.pcb_port_id;if(!id||seen.has(id)||!o.connectedTo?.some((id:any)=>ids.has(id)))return[];seen.add(id);return[{...o.center,layer:o.layers.includes('top')?'top':o.layers[0],pcb_port_id:id,pointId:id}]});if(!points.length)throw Error('Missing fixed net definition '+name);connections.push({name,source_trace_id:t.source_trace_id,pointsToConnect:points,nominalTraceWidth:native.minTraceWidth??.1});known.add(name)}
 return{...native,connections}
}
