/** Automatic TOP/BOTTOM path generation, including two legal full-stack transitions.
 * Matching operates on generated wire runs before a trace is accepted. */
export function* routeHybridOrdinary(state:any,c:any,bus:any,original:any,preference='top',soft:any[]=[],penalty=10,historyPoints:any[]=[],reservations:any[]=[]):Generator<void,any|null>{
 const fixedLength=fixedRouteLength(state,c.name);bus={...bus,minLength:Math.max(0,bus.minLength-fixedLength),maxLength:bus.maxLength-fixedLength};const surface=c.pointsToConnect[0].layer,carrier=surface==='top'?'bottom':'top';
 const step=.1,p=c.pointsToConnect,slack=Math.max(5,Math.min(14,(bus.maxLength-Math.hypot(p[1].x-p[0].x,p[1].y-p[0].y))/2+2)),bounds={minX:Math.max(state.bounds.minX,Math.floor(Math.min(p[0].x,p[1].x)-slack)),maxX:Math.min(state.bounds.maxX,Math.ceil(Math.max(p[0].x,p[1].x)+slack)),minY:Math.max(state.bounds.minY,Math.floor(Math.min(p[0].y,p[1].y)-slack)),maxY:Math.min(state.bounds.maxY,Math.ceil(Math.max(p[0].y,p[1].y)+slack))},local={...state,bounds,connections:[c],buses:[{...bus,connectionNames:[c.name]}],differentialPairs:[],traces:[...state.traces,...reservations]};const guards:any[]=[];for(const t of state.traces??[]){if(t.connection_name!==c.name&&t.source_trace_id!==c.name&&t.source_trace_id!==c.source_trace_id)continue;const via=t.route.find((q:any)=>q.route_type==='via');if(!via||!p.some((q:any)=>Math.hypot(via.x-q.x,via.y-q.y)<1e-7))continue;const run=t.route.filter((q:any)=>q.route_type==='wire'&&q.layer==='top');if(run.length<2)continue;const a=run[0],z=run.at(-1),span=Math.hypot(z.x-a.x,z.y-a.y),cut=(via.via_diameter??.5)/2;if(span<=cut)continue;const end={...z,x:z.x+(a.x-z.x)*cut/span,y:z.y+(a.y-z.y)*cut/span};guards.push({type:'pcb_trace',pcb_trace_id:'owned_stub_guard_'+t.pcb_trace_id,connection_name:'__owned_stub_keepout__',route:[a,end]})}local.traces=[...local.traces,...guards]
 const costOf=makeNegotiatedRouteCost(local,soft,historyPoints);let best:any=null,bestScore=Infinity;const consider=(trace:any)=>{if(!trace)return;const score=costOf(trace);if(score<bestScore){bestScore=score;best=trace}}
 function fit(trace:any,bankCost?:any){
  const chunks:any[]=[];let wires:any[]=[];const flush=()=>{if(wires.length){chunks.push({wires});wires=[]}}
  for(const point of trace.route){if(point.route_type==='via'){flush();chunks.push({via:point})}else wires.push(point)}flush()
  for(const chunk of chunks){if(!chunk.wires||chunk.wires.length<2)continue;const run={...trace,route:chunk.wires},input={...local,connections:[{...c,pointsToConnect:[chunk.wires[0],chunk.wires.at(-1)]}]};chunk.wires=chamferOrdinaryCorners(input,[run])[0].route}
  const build=()=>{const route:any[]=[],curvedSegments:number[]=[];for(const chunk of chunks){if(chunk.via)route.push(chunk.via);else{const start=route.length;route.push(...chunk.wires);for(const i of chunk.curves??[])curvedSegments.push(start+i)}}return{...trace,route,...(curvedSegments.length?{curvedSegments}:{})}}
  let result=build(),delta=bus.minLength-length(result.route)
  if(delta>1e-7){
   const order=chunks.filter(x=>x.wires?.length>1).sort((a,b)=>Number(b.wires[0].layer==='bottom')-Number(a.wires[0].layer==='bottom')||length(b.wires)-length(a.wires))
   let matched=false
   for(const selected of order){
    const held=chunks.filter(x=>x!==selected).flatMap((x,i)=>x.via?[{type:'pcb_trace',pcb_trace_id:'held_via_'+i,connection_name:c.name,source_trace_id:c.source_trace_id,route:[{route_type:'wire',x:x.via.x,y:x.via.y,layer:x.via.from_layer,width:.1},x.via,{route_type:'wire',x:x.via.x,y:x.via.y,layer:x.via.to_layer,width:.1}]}]:[{type:'pcb_trace',pcb_trace_id:'held_run_'+i,connection_name:'__held_other_run__',route:x.wires}]),run={...trace,route:selected.wires},input={...local,connections:[{...c,pointsToConnect:[selected.wires[0],selected.wires.at(-1)]}],traces:[...local.traces,...held]},target=length(selected.wires)+delta+fixedLength
    try{const tuned=tuneSmoothLengths(input,[run],new Map([[c.name,target]]),{maxCandidates:2048,packMeanders:true,candidateScore:costOf})[0];selected.wires=tuned.route;selected.curves=tuned.curvedSegments;result=build();if(length(result.route)>=bus.minLength-1e-7){matched=true;break}}catch{}
   }
   if(!matched){console.log('Hybrid tuning bank unavailable',c.name,length(result.route),bus.minLength);return null}
  }
  const total=length(result.route);if(total<bus.minLength-1e-7||total>bus.maxLength+1e-7)return null
  if(!viaChecks(original,[result]).valid)return null
  const drc=validateRoutedCopperDrc({inputSrj:original,routedSrj:{...original,traces:[...state.traces,result]},clearance:original.minTraceToPadEdgeClearance,allowBlindAndBuriedVias:false});if(!drc.valid){console.log('Hybrid DRC candidate rejected',c.name,JSON.stringify(drc.issues.slice(0,2)));return null}
  return result
 }
 const top={...c,pointsToConnect:p},scene=new VectorScene(local,top,.1,fixedCopper(local)),s=new GridVisibilitySearch(scene,top.pointsToConnect[0],top.pointsToConnect[1],[],0,undefined,{bounds,step,maxLength:bus.maxLength,checkReachability:true,paretoLength:true});let count=0
 try{while(preference==='top'&&!soft.length&&!s.solved&&!s.failed&&count++<800){s.step();yield}if(!soft.length&&s.solved&&preference==='top'){const t=fit({type:'pcb_trace',pcb_trace_id:'hybrid_'+c.name,connection_name:c.name,source_trace_id:c.source_trace_id,route:s.result.map(q=>({...q,route_type:'wire',layer:'top',width:.1}))});if(t)return t}}finally{s.cancel()}
  const N=(Math.ceil((bounds.maxX-bounds.minX)/step)+1)*(Math.ceil((bounds.maxY-bounds.minY)/step)+1),history=[new Float32Array(N),new Float32Array(N)],nx=Math.ceil((bounds.maxX-bounds.minX)/step)+1;for(const p of historyPoints){const ix=Math.round((p.x-bounds.minX)/step),iy=Math.round((p.y-bounds.minY)/step);for(let dx=-2;dx<=2;dx++)for(let dy=-2;dy<=2;dy++){const x=ix+dx,y=iy+dy;if(x>=0&&x<nx&&y>=0&&y*nx+x<N)history[p.layer==='top'?0:1][y*nx+x]+=p.cost}}const router=new NativeCarrierRouter({...local,allowedLayers:[carrier],nativeSurfaceLayer:surface},step,history);
 for(const transitionStages of (surface===p[1].layer?(bus.preferredLayer===carrier?[2,0,4]:[0,2,4]):[1,3]))for(const external of (transitionStages===0||surface!==p[1].layer?[true]:[false,true])){if(transitionStages===4&&bestScore<500)continue;
  const g=router.route(top,{allowExternalTransitions:external,carrierRegion:bounds,maxLength:bus.maxLength,transitionStages,softTraces:soft,softPenalty:penalty,maxExpansions:1500000});let n=g.next()
 try{while(!n.done){yield;n=g.next()}if(n.value){console.log('Hybrid raw candidate',c.name,transitionStages,external,length(n.value.trace.route));const result=fit(n.value.trace,n.value.bankCost);consider(result);if(bestScore===0)return best}else console.log('Hybrid path search incomplete',c.name,transitionStages)}finally{if(!n.done)g.return(null)}
 }
 if(false){
  const retry=new GridVisibilitySearch(scene,top.pointsToConnect[0],top.pointsToConnect[1],[],0,undefined,{bounds,step,maxLength:bus.maxLength,checkReachability:true,paretoLength:true});let rounds=0
  try{while(!retry.solved&&!retry.failed&&rounds++<800){retry.step();yield}if(retry.solved){const t=fit({type:'pcb_trace',pcb_trace_id:'hybrid_'+c.name,connection_name:c.name,source_trace_id:c.source_trace_id,route:retry.result.map(q=>({...q,route_type:'wire',layer:'top',width:.1}))});if(t)return t}}finally{retry.cancel()}
 }
 return best
}
