import {routeHybridOrdinary as rankFaces} from './route-hybrid-ordinary-endpoint-portfolio'
import {routeHybridOrdinary as fallback} from './route-hybrid-ordinary-reachable-fallback'
/** Rank physical via faces at either endpoint even when the declared face has a proposal.
 * The declared handoff face does not restrict an existing through barrel. */
export function* routeHybridOrdinary(state:any,c:any,...args:any[]):Generator<void,any|null>{
 const ownsSourceVia=(state.traces??[]).filter((t:any)=>t.connection_name===c.name||t.source_trace_id===c.name||t.source_trace_id===c.source_trace_id).some((t:any)=>t.route.some((q:any)=>q.route_type==='via'&&c.pointsToConnect.some((p:any)=>Math.hypot(p.x-q.x,p.y-q.y)<1e-7)&&['top','bottom'].every(l=>(q.layers??[]).includes(l))))
 return yield* (ownsSourceVia?rankFaces:fallback)(state,c,...args)
}
