const key=(p:any,layer:string)=>`${p.x.toFixed(7)},${p.y.toFixed(7)},${layer}`
export function connectivity(connection:any,traces:any[]){
 const parent=new Map<string,string>(),root=(x:string):string=>{if(!parent.has(x))parent.set(x,x);const p=parent.get(x)!;if(p===x)return x;const r=root(p);parent.set(x,r);return r},join=(a:string,b:string)=>parent.set(root(a),root(b))
 for(const trace of traces){const route=trace.route;for(let i=0;i<route.length;i++){const p=route[i];if(p.route_type==='wire'){root(key(p,p.layer));const prior=route[i-1];if(prior?.route_type==='wire'&&prior.layer===p.layer)join(key(prior,p.layer),key(p,p.layer))}else if(p.route_type==='via'){const layers=p.layers??[p.from_layer,p.to_layer];for(const layer of layers)join(key(p,layers[0]),key(p,layer))}}}
 const points=connection.pointsToConnect.map((p:any)=>key(p,p.layer));return points.every((p:string)=>parent.has(p))&&points.every((p:string)=>root(p)===root(points[0]))
}
export function viaChecks(input:any,traces:any[]){let total=0;const errors:any[]=[];const layers=['top','inner1','inner2','bottom'];for(const trace of traces)for(const p of trace.route){if(p.route_type!=='via')continue;total++;if(p.via_hole_diameter<.3-1e-7||p.via_diameter<.5-1e-7||!layers.every(l=>(p.layers??layers.slice(Math.min(layers.indexOf(p.from_layer),layers.indexOf(p.to_layer)),Math.max(layers.indexOf(p.from_layer),layers.indexOf(p.to_layer))+1)).includes(l)))errors.push({trace:trace.pcb_trace_id,point:p,reason:'size/span'});for(const o of input.obstacles.filter((o:any)=>o.componentId&&o.circuitJsonMetadata?.pcb_smtpad_id)){const angle=-(o.ccwRotationDegrees??0)*Math.PI/180,rx=p.x-o.center.x,ry=p.y-o.center.y,dx=Math.abs(rx*Math.cos(angle)-ry*Math.sin(angle)),dy=Math.abs(rx*Math.sin(angle)+ry*Math.cos(angle)),edge=o.shape==='circle'?Math.hypot(dx,dy)-o.width/2:Math.hypot(Math.max(0,dx-o.width/2),Math.max(0,dy-o.height/2));if(edge<p.via_diameter/2-1e-7)errors.push({trace:trace.pcb_trace_id,pad:o.circuitJsonMetadata.pcb_smtpad_id,reason:'via-in-pad'})}}return{total,valid:!errors.length,errors}}
export function traceBelongsTo(connection:any,trace:any){return trace.connection_name===connection.name||trace.source_trace_id===connection.name||(!!connection.source_trace_id&&trace.source_trace_id===connection.source_trace_id)}
