import {routeHybridOrdinary as rankFaces} from './route-hybrid-ordinary-selfclear-portfolio'
import {routeHybridOrdinary as fallback} from './route-hybrid-ordinary-selfclear-fallback'
/** Rank physical source-via faces even when the declared face has a proposal.
 * Preserve existing target-only fallback to avoid changing unrelated proposals. */
export function* routeHybridOrdinary(state:any,c:any,...args:any[]):Generator<void,any|null>{
 const p=c.pointsToConnect[0],ownsSourceVia=(state.traces??[]).filter((t:any)=>t.connection_name===c.name||t.source_trace_id===c.name||t.source_trace_id===c.source_trace_id).some((t:any)=>t.route.some((q:any)=>q.route_type==='via'&&Math.hypot(p.x-q.x,p.y-q.y)<1e-7&&['top','bottom'].every(l=>(q.layers??[]).includes(l))))
 return yield* (ownsSourceVia?rankFaces:fallback)(state,c,...args)
}
