import {DogboneAutorouter} from '../dogbone-pr6-paired-validation/lib/index'
/** Fresh BGA fanouts in board-world mm (+X right,+Y up). No sites are prescribed. */
export function generateFeasibleSupportFanouts(input:any):any[]{
 const counts=new Map<string,number>();for(const o of input.obstacles)if(o.componentId&&o.shape==='circle')counts.set(o.componentId,(counts.get(o.componentId)??0)+1)
 const tasks:any[]=[],owners=new Map<string,any>(),seen=new Set<string>()
 for(const c of [...input.connections].sort((a:any,b:any)=>b.pointsToConnect.length-a.pointsToConnect.length))for(const p of c.pointsToConnect){
  const pad=input.obstacles.find((o:any)=>o.circuitJsonMetadata?.pcb_port_id===p.pcb_port_id);if(!pad||(counts.get(pad.componentId)??0)<60||seen.has(p.pcb_port_id))continue
  seen.add(p.pcb_port_id);const other=c.pointsToConnect.find((q:any)=>q.pcb_port_id!==p.pcb_port_id);if(!other)throw Error('Support fanout lacks another net endpoint')
  const direct=input.connections.find((d:any)=>d.source_trace_id&&d.pointsToConnect.every((q:any)=>c.pointsToConnect.some((p:any)=>p.pcb_port_id===q.pcb_port_id))),sourceId=direct?.source_trace_id??c.source_trace_id??c.name,name=c.name+'__escape_'+p.pcb_port_id
  tasks.push({...c,name,source_trace_id:sourceId,pointsToConnect:[p,other]});owners.set(name,{connection_name:c.name,source_trace_id:sourceId})
 }
 const feasible=tasks.filter(task=>{const f=new DogboneAutorouter({input:{...input,connections:[task]},fanoutRoutingLayers:['bottom']});try{f.solveSync();return true}catch(error){if(!String(error).includes('No complete local dogbone assignment'))throw error;console.log('GLOBAL_SUPPORT_ESCAPE_REQUIRED',task.name);return false}})
 if(!feasible.length)throw Error('No local support fanouts found')
 const f=new DogboneAutorouter({input:{...input,connections:feasible},fanoutRoutingLayers:['bottom']}),traces=f.solveSync().map((t:any)=>({...t,...owners.get(t.connection_name)}));console.log('JOINT_SUPPORT_FANOUTS',traces.length);return traces
}
