/** Search stages are planning state, not distinct copper layers. Remove cycles
 * that revisit the same physical cell and layer before emitting and matching
 * the generated path. Retained edges still join at the identical grid cell. */
export function erasePhysicalGridLoops(ids: readonly number[], cellsPerLayer: number): number[] {
  const path: number[] = [], positions = new Map<number, number>()
  const key = (id: number) => (Math.floor(id / cellsPerLayer) % 2) * cellsPerLayer + id % cellsPerLayer
  for (const id of ids) {
    const physical = key(id), previous = positions.get(physical)
    if (previous !== undefined) {
      while (path.length > previous + 1) positions.delete(key(path.pop()!))
    } else {
      positions.set(physical, path.length)
      path.push(id)
    }
  }
  return path
}
