import {routeHybridOrdinary as routeDeclared} from './route-hybrid-ordinary-boundary-cached'
/** Keep the established proposal first. If it cannot route, reuse the other
 * actual surface of an owned through-via rather than treating a handoff's
 * declared layer as the barrel's physical layer span. */
export function* routeHybridOrdinary(state:any,c:any,bus:any,original:any,preference='global',soft:any[]=[],penalty=10,history:any[]=[],reservations:any[]=[]):Generator<void,any|null>{
 function* attempt(connection:any):Generator<void,any|null>{const g=routeDeclared(state,connection,bus,original,preference,soft,penalty,history,reservations);let n=g.next();while(!n.done){yield;n=g.next()}return n.value}
 const first=yield* attempt(c);if(first)return first
 const own=(state.traces??[]).filter((t:any)=>t.connection_name===c.name||t.source_trace_id===c.name||t.source_trace_id===c.source_trace_id),layers=(p:any)=>{const via=own.flatMap((t:any)=>t.route).find((q:any)=>q.route_type==='via'&&Math.hypot(p.x-q.x,p.y-q.y)<1e-7);return via&&['top','bottom'].every(l=>(via.layers??[]).includes(l))?['top','bottom']:[p.layer]}
 for(const from of layers(c.pointsToConnect[0]))for(const to of layers(c.pointsToConnect[1])){if(from===c.pointsToConnect[0].layer&&to===c.pointsToConnect[1].layer)continue;const result=yield* attempt({...c,pointsToConnect:[{...c.pointsToConnect[0],layer:from},{...c.pointsToConnect[1],layer:to}]});if(result)return result}
 return null
}
