import {existingViaTerminalLayers} from './existing-via-handoffs'
import {effectiveCarrierLayers} from './effective-carrier-layers'
import {GridVisibilitySearch} from './grid-visibility'
import {fixedCopper,VectorScene} from './vector-scene'
import {maximumCarrierLength} from './route-lengths'
import type {SimpleRouteJson} from './types'
export type ViaReachability=Map<string,Map<string,boolean|undefined>>
/** Cooperative, bounded allocation hint. Unknown domains remain available. */
export function* existingViaReachability(input:SimpleRouteJson,maxSteps=10000):Generator<void,ViaReachability>{
 const result:ViaReachability=new Map(),hard=fixedCopper(input)
 for(const connection of input.connections){
  if(connection.pointsToConnect.length!==2||!Number.isFinite(maximumCarrierLength(input,connection.name)))continue
  const contact=connection.pointsToConnect.map(point=>existingViaTerminalLayers(input,connection,point))
  if(contact.some(options=>!options.length))continue
  const allowed=effectiveCarrierLayers(input,connection).filter(layer=>contact.every(options=>options.includes(layer)))
  if(allowed.length<2)continue
  const outcomes=new Map<string,boolean|undefined>();result.set(connection.name,outcomes)
  const width=connection.width??connection.nominalTraceWidth??input.buses?.find(b=>b.connectionNames.includes(connection.name))?.traceWidth??input.minTraceWidth
  for(const layer of allowed){
   const local={...connection,pointsToConnect:connection.pointsToConnect.map(point=>({...point,layer}))},scene=new VectorScene(input,local,width,hard),search=new GridVisibilitySearch(scene,local.pointsToConnect[0],local.pointsToConnect[1],[],0,undefined,{checkReachability:true,maxLength:maximumCarrierLength(input,connection.name),paretoLength:true})
   let steps=0
   try{while(!search.solved&&!search.failed&&steps++<maxSteps){search.step();yield}outcomes.set(layer,search.solved?true:search.failed?false:undefined)}finally{search.cancel()}
  }
 }
 return result
}
