import {DogboneAutorouter} from '../dogbone-pr6-paired-validation/lib/index'
/** Automatically reserve native pad-to-via escapes for selected later-phase
 * BGA connections. No sites or copper coordinates are prescribed. */
export async function createFutureBgaEscapes(input:any):Promise<any>{
 const listeners=new Map<string,any[]>();let result:any,timer:any,stopped=false
 const router={input,isRouting:false,on(type:string,f:any){listeners.set(type,[...listeners.get(type)??[],f])},start(){router.isRouting=true;timer=setTimeout(()=>{try{
  const counts=new Map<string,number>();for(const o of input.obstacles)if(o.componentId&&o.shape==='circle')counts.set(o.componentId,(counts.get(o.componentId)??0)+1)
  const tasks:any[]=[],originals=new Map<string,any>(),seen=new Set<string>();
  for(const c of input.connections)for(const p of c.pointsToConnect){const pad=input.obstacles.find((o:any)=>o.circuitJsonMetadata?.pcb_port_id===p.pcb_port_id);if(!pad||(counts.get(pad.componentId)??0)<60||seen.has(p.pcb_port_id))continue;seen.add(p.pcb_port_id);const other=c.pointsToConnect.find((q:any)=>q.pcb_port_id!==p.pcb_port_id)??input.obstacles.filter((o:any)=>o.circuitJsonMetadata?.pcb_port_id&&o.circuitJsonMetadata.pcb_port_id!==p.pcb_port_id&&o.connectedTo?.includes(c.name)).map((o:any)=>({...o.center,layer:o.layers[0],pcb_port_id:o.circuitJsonMetadata.pcb_port_id})).sort((a:any,b:any)=>Math.hypot(a.x-p.x,a.y-p.y)-Math.hypot(b.x-p.x,b.y-p.y))[0];if(!other)continue;const name=c.name+'__escape_'+p.pcb_port_id;tasks.push({...c,name,source_trace_id:c.source_trace_id??c.name,pointsToConnect:[p,other]});originals.set(name,c)}
  if(!tasks.length)throw Error('No selected BGA ports for escape phase');const feasible=tasks.filter(task=>{const candidate=new DogboneAutorouter({input:{...input,connections:[task]},fanoutRoutingLayers:['bottom']});try{candidate.solveSync();return true}catch(error){console.log('BGA_ESCAPE_DEFERRED',task.name,String(error));return false}});if(!feasible.length)throw Error('No selected BGA ports have legal local escapes');const f=new DogboneAutorouter({input:{...input,connections:feasible},fanoutRoutingLayers:['bottom']}),fresh=f.solveSync();result=[...(input.traces??[]),...fresh.map((t:any)=>{const c=originals.get(t.connection_name);return{...t,connection_name:c.name,source_trace_id:c.source_trace_id??c.name}})];console.log('FUTURE_BGA_ESCAPES',tasks.length,'generated',fresh.length);router.isRouting=false;if(!stopped)for(const fn of listeners.get('complete')??[])fn({type:'complete',traces:result})
 }catch(error){router.isRouting=false;if(!stopped)for(const fn of listeners.get('error')??[])fn({type:'error',error})}},0)},stop(){stopped=true;router.isRouting=false;clearTimeout(timer)},getOutputSimpleRouteJson(){if(!result)throw Error('Escapes incomplete');return{...input,traces:result}}};return router
}
