import {routeHybridOrdinary as routeDeclared} from './route-hybrid-ordinary-boundary-selfclear'
import {makeNegotiatedRouteCost} from './negotiated-route-cost'
/** Rank every physically reachable endpoint surface, including owned via
 * lands. A declared handoff layer does not reduce a full-stack barrel's span. */
export function* routeHybridOrdinary(state:any,c:any,bus:any,original:any,preference='global',soft:any[]=[],penalty=10,history:any[]=[],reservations:any[]=[]):Generator<void,any|null>{
 const own=(state.traces??[]).filter((t:any)=>t.connection_name===c.name||t.source_trace_id===c.name||t.source_trace_id===c.source_trace_id),layers=(p:any)=>{const via=own.flatMap((t:any)=>t.route).find((q:any)=>q.route_type==='via'&&Math.hypot(p.x-q.x,p.y-q.y)<1e-7);return via&&['top','bottom'].every(l=>(via.layers??[]).includes(l))?[p.layer,...['top','bottom'].filter(l=>l!==p.layer)]:[p.layer]},costOf=makeNegotiatedRouteCost(state,soft,history);let best:any=null,bestCost=Infinity
 for(const from of layers(c.pointsToConnect[0]))for(const to of layers(c.pointsToConnect[1])){
  const connection={...c,pointsToConnect:[{...c.pointsToConnect[0],layer:from},{...c.pointsToConnect[1],layer:to}]},g=routeDeclared(state,connection,bus,original,preference,soft,penalty,history,reservations);let n=g.next()
  try{while(!n.done){yield;n=g.next()}if(n.value){const score=costOf(n.value);if(score<bestCost){bestCost=score;best=n.value}if(score===0)return best}}finally{if(!n.done)g.return(null)}
 }
 return best
}
