import {fixedCopper} from './solver-reachable-handoff-layers/lib/vector-scene'
import {CopperConflictIndex} from './solver-reachable-handoff-layers/lib/copper-conflict-index'
/** Penalize learned congestion in final path/bank selection as well as A*.
 * Sampling is length-weighted so curve tessellation cannot inflate cost. */
export function makeNegotiatedRouteCost(state:any,soft:any[],points:any[]){
 const groups=soft.map(t=>fixedCopper({...state,obstacles:[],traces:[t]})),idx=new CopperConflictIndex(),maps=[new Map<string,number>(),new Map<string,number>()]
 for(const p of points){const x=Math.round(p.x*10),y=Math.round(p.y*10),map=maps[p.layer==='top'?0:1];for(let dx=-2;dx<=2;dx++)for(let dy=-2;dy<=2;dy++){const key=`${x+dx},${y+dy}`;map.set(key,(map.get(key)??0)+p.cost)}}
 const at=(p:any,layer:string)=>(maps[layer==='top'?0:1].get(`${Math.round(p.x*10)},${Math.round(p.y*10)}`)??0)
 return (trace:any)=>{const copper=fixedCopper({...state,obstacles:[],traces:[trace]}),conflicts=groups.reduce((s,g)=>s+Number(!!idx.firstConflict(copper,g,(state.minTraceToPadEdgeClearance??.1)-1e-8)),0);let learned=0,vias=0
  for(let i=0;i<trace.route.length;i++){const a=trace.route[i],b=trace.route[i+1];if(a.route_type==='via'){vias++;learned+=2*(at(a,'top')+at(a,'bottom'))}if(!b||a.route_type!=='wire'||b.route_type!=='wire'||a.layer!==b.layer)continue;const span=Math.hypot(b.x-a.x,b.y-a.y),count=Math.max(1,Math.ceil(span/.1));for(let k=0;k<count;k++){const f=(k+.5)/count;learned+=span/.1/count*at({x:a.x+(b.x-a.x)*f,y:a.y+(b.y-a.y)*f},a.layer)}}
  return 500*conflicts+30*vias+4*learned
 }
}
