import {getCopperLayerNames} from '@tscircuit/fanout-solver'
import type {Connection,SimpleRouteJson,Terminal} from './types'

/** Actual same-net barrel contact at a supplied terminal; no geometry is moved. */
export function existingViaTerminalLayers(input:SimpleRouteJson,connection:Connection,point:Terminal):string[]{
 const physical=getCopperLayerNames(input.layerCount),names=new Set([connection.name,connection.source_trace_id].filter(Boolean)),reachable=new Set<string>()
 for(const trace of input.traces??[]){
  if(!names.has(trace.connection_name)&&!names.has(trace.source_trace_id))continue
  for(const via of trace.route){
   if(via.route_type!=='via'||Math.hypot(via.x-point.x,via.y-point.y)>1e-8)continue
   const a=physical.indexOf(via.from_layer),b=physical.indexOf(via.to_layer)
   const span=via.layers??(a>=0&&b>=0?physical.slice(Math.min(a,b),Math.max(a,b)+1):[])
   if(span.includes(point.layer))for(const layer of span)reachable.add(layer)
  }
 }
 return physical.filter(layer=>reachable.has(layer)&&(!point.layers||point.layers.includes(layer)))
}

export function withExistingViaTerminalLayers(input:SimpleRouteJson):SimpleRouteJson{
 let changed=false
 const connections=input.connections.map(connection=>({...connection,pointsToConnect:connection.pointsToConnect.map(point=>{
  const layers=existingViaTerminalLayers(input,connection,point)
  if(layers.length<2||!layers.includes(point.layer)||JSON.stringify(layers)===JSON.stringify(point.layers))return point
  changed=true;return{...point,layers}
 })}))
 return changed?{...input,connections}:input
}

/** Select an existing conductor layer before asking for new local dogbones. */
export function selectExistingViaTerminalLayers(input:SimpleRouteJson,targets:ReadonlyMap<string,string>):SimpleRouteJson{
 let changed=false
 const connections=input.connections.map(connection=>({...connection,pointsToConnect:connection.pointsToConnect.map(point=>{
  const target=targets.get(connection.name)
  if(!target||target===point.layer||!existingViaTerminalLayers(input,connection,point).includes(target))return point
  changed=true;return{...point,layer:target}
 })}))
 return changed?{...input,connections}:input
}
